// Security + validation gate: only the Lambda / workflow B (which hold WEBHOOK_SECRET) may trigger this workflow.
const secret = $env.WEBHOOK_SECRET;
const first = $input.first().json;
const got = (first.headers || {})['x-webhook-secret'];
if (secret && got !== secret) throw new Error('Invalid webhook secret');
const batchId = (first.body || {}).batch_id || '';
if (!/^[0-9a-f-]{36}$/i.test(batchId)) throw new Error('Invalid batch_id');
return [{ json: { batch_id: batchId } }];

// SAFETY: never email addresses from the CSV. Recipients come only from TEST_EMAIL_ALIASES (round-robin).
const aliases = ($env.TEST_EMAIL_ALIASES || '').split(',').map(s => s.trim()).filter(Boolean);
if (!aliases.length) throw new Error('Set TEST_EMAIL_ALIASES in .env - refusing to email CSV addresses.');
const max = parseInt($env.DEMO_MAX_EMAILS || '5', 10);
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
return $input.all().slice(0, max).map((it, idx) => {
  const u = it.json;
  const rows = u.products.map((p, i) =>
    `<tr><td style="padding:8px;border-bottom:1px solid #eee"><b>${i + 1}. ${esc(p.name)}</b><br>` +
    `<span style="color:#666">${esc(p.provider)}</span>` +
    (p.reason && p.reason !== 'llm_unavailable' ? `<br><i style="color:#555">${esc(p.reason)}</i>` : '') + `</td>` +
    `<td style="padding:8px;border-bottom:1px solid #eee;text-align:right">${esc(p.rate)}% p.a.</td></tr>`).join('');
  const html = `<div style="font-family:Arial,sans-serif;max-width:560px">` +
    `<h2>Personal loans you may qualify for</h2>` +
    `<p>Hi ${esc(u.user_id)}, based on your profile you may be eligible for these personal loans:</p>` +
    `<table style="width:100%;border-collapse:collapse">${rows}</table>` +
    `<p style="color:#888;font-size:12px">Indicative eligibility only; final approval is up to the lender. ` +
    `(Demo email - original CSV address ${esc(u.email.replace(/^(.).*(@.*)$/, '$1***$2'))} was NOT contacted.)</p></div>`;
  return { json: { to: aliases[idx % aliases.length], user_id: u.user_id,
                   subject: `${u.products.length} personal loan option(s) you may qualify for`,
                   html, match_ids: u.match_ids } };
});
